def _encode_varint(value: int) -> bytes:
    if value < 0:
        value &= (1 << 64) - 1

    result = bytearray()

    while value > 0x7F:
        result.append((value & 0x7F) | 0x80)
        value >>= 7

    result.append(value)

    return bytes(result)


def _decode_varint(data: bytes, offset: int) -> tuple[int, int]:
    value = 0
    shift = 0

    while offset < len(data):
        byte = data[offset]
        offset += 1

        value |= (byte & 0x7F) << shift

        if not byte & 0x80:
            return value, offset

        shift += 7

        if shift >= 70:
            raise DecodeError("Too many bytes when decoding varint.")

    raise DecodeError("Truncated varint.")


def _encode_key(field_number: int, wire_type: int) -> bytes:
    return _encode_varint((field_number << 3) | wire_type)


def _decode_key(value: int) -> tuple[int, int]:
    return value >> 3, value & 0x07


def _encode_length_delimited(value: bytes) -> bytes:
    return _encode_varint(len(value)) + value


def _decode_length_delimited(
    data: bytes,
    offset: int,
) -> tuple[bytes, int]:
    length, offset = _decode_varint(data, offset)
    end = offset + length

    if end > len(data):
        raise DecodeError("Truncated length-delimited field.")

    return data[offset:end], end


def _encode_field(field, value):
    if field.type == _BOOL:
        return _encode_key(field.number, 0) + _encode_varint(int(value))

    if field.type in (_INT32, _INT64, _UINT32):
        return _encode_key(field.number, 0) + _encode_varint(value)

    if field.type == _ENUM:
        if isinstance(value, str):
            value = field.enum.Value(value)

        return _encode_key(field.number, 0) + _encode_varint(value)

    if field.type == _BYTES:
        return _encode_key(field.number, 2) + _encode_length_delimited(value)

    if field.type == _STRING:
        return _encode_key(field.number, 2) + _encode_length_delimited(value.encode("utf-8"))

    if field.type == _MESSAGE:
        return _encode_key(field.number, 2) + _encode_length_delimited(value.SerializeToString())

    raise NotImplementedError(
        f"Encoding field type {field.type!r} is not implemented.",
    )


def _decode_field_varint(field, value):
    if field.type == _BOOL:
        return bool(value)

    if field.type == _UINT32:
        return value & 0xFFFFFFFF

    if field.type == _INT32:
        value &= 0xFFFFFFFF
        if value & 0x80000000:
            value -= 1 << 32
        return value

    if field.type == _INT64:
        value &= 0xFFFFFFFFFFFFFFFF
        if value & 0x8000000000000000:
            value -= 1 << 64
        return value

    if field.type == _ENUM:
        return value

    raise DecodeError(
        f"Cannot decode field type {field.type!r} as a varint.",
    )


def _decode_field_length_delimited(field, value):
    if field.type == _BYTES:
        return value

    if field.type == _STRING:
        try:
            return value.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise DecodeError(
                f"Invalid UTF-8 in field {field.name!r}.",
            ) from exc

    if field.type == _MESSAGE:
        message = field.message()
        message.ParseFromString(value)
        return message

    raise DecodeError(
        f"Cannot decode field type {field.type!r} as length-delimited.",
    )


def _skip_field(data, offset, wire_type):
    if wire_type == 0:
        _, offset = _decode_varint(data, offset)
        return offset

    if wire_type == 1:
        end = offset + 8

        if end > len(data):
            raise DecodeError("Truncated 64-bit field.")

        return end

    if wire_type == 2:
        _, offset = _decode_length_delimited(data, offset)
        return offset

    if wire_type == 5:
        end = offset + 4

        if end > len(data):
            raise DecodeError("Truncated 32-bit field.")

        return end

    raise DecodeError(
        f"Unsupported wire type {wire_type}.",
    )


# --- begin compat/construct.py ---
#
# Minimal construct compatibility required by the bundled pywidevine implementation.
#
# This is intentionally not a general-purpose construct implementation.


_DEVICE_TYPES = {
    1: "CHROME",
    2: "ANDROID",
}


class ConstructError(Exception):
    pass


class Container(dict):
    __getattr__ = dict.__getitem__
    __setattr__ = dict.__setitem__


class _Struct:
    def __init__(self, version=None):
        self.version = version

    def parse(self, data):
        try:
            if data[:3] != b"WVD":
                raise ConstructError("invalid signature")

            version = data[3]

            if self.version is None:
                return Container(version=version)

            if version != self.version:
                raise ConstructError("invalid version")

            type_, security_level = data[4:6]

            private_key_len = struct.unpack_from(">H", data, 7)[0]
            offset = 9
            private_key = data[offset : offset + private_key_len]
            offset += private_key_len

            client_id_len = struct.unpack_from(">H", data, offset)[0]
            offset += 2
            client_id = data[offset : offset + client_id_len]
            offset += client_id_len

            result = Container(
                version=version,
                type_=_DEVICE_TYPES[type_],
                security_level=security_level,
                flags={},
                private_key=private_key,
                client_id=client_id,
            )

            if version == 1:
                vmp_len = struct.unpack_from(">H", data, offset)[0]
                offset += 2
                result.vmp = data[offset : offset + vmp_len]

            return result

        except (IndexError, KeyError, struct.error) as e:
            raise ConstructError(str(e)) from e

    def parse_stream(self, stream):
        return self.parse(stream.read())

    def build(self, obj):
        private_key = obj["private_key"]
        client_id = obj["client_id"]
        type_ = obj["type_"]

        if isinstance(type_, str):
            type_ = {name: value for value, name in _DEVICE_TYPES.items()}[type_]
        elif hasattr(type_, "value"):
            type_ = type_.value

        return (
            b"WVD"
            + bytes((2, type_, obj["security_level"], 0))
            + struct.pack(">H", len(private_key))
            + private_key
            + struct.pack(">H", len(client_id))
            + client_id
        )


class _Structures:
    header = _Struct()
    v1 = _Struct(1)
    v2 = _Struct(2)


